import { hasSupabaseConfig, supabase } from "./supabase";

const GENERIC_ERROR = "Questions could not be generated. Try again.";

export class GenerationRequestError extends Error {
  constructor(message) {
    super(message);
    this.name = "GenerationRequestError";
  }
}

// Questions are generated by the authenticated generate-mcq Edge Function; the browser never holds an AI key.
export async function requestGeneratedQuestions({ pages, count, difficulty, avoidStems = [], signal }) {
  if (!hasSupabaseConfig) throw new GenerationRequestError("Question generation needs a connection to the server.");

  const { data, error } = await supabase.functions.invoke("generate-mcq", {
    body: { requestKey: crypto.randomUUID(), pages, count, difficulty, avoidStems },
    signal,
  });
  if (signal?.aborted) throw new globalThis.DOMException("Generation was cancelled.", "AbortError");
  if (error) {
    let message = "";
    try {
      message = (await error.context?.json?.())?.error || "";
    } catch {
      message = "";
    }
    throw new GenerationRequestError(message || GENERIC_ERROR);
  }
  return {
    questions: Array.isArray(data?.questions) ? data.questions : [],
    sample: Boolean(data?.sample),
  };
}
